questionvariables.text:
validate_numeric(ex) := block([sx], sx: ev(ex, simp), if listofvars(ex) = [] and freeof(%i, sx) then "" else "Type a number in each box, not a letter.");
/* Design: image of a triangle under a matrix. Source: original. Curated list; the transpose and diagonal-only products differ from the answer on every entry. */
tlist: [[matrix([0,-1],[3,2]),[-2,-1],[-2,-3],[4,4]],[matrix([2,-2],[2,-3]),[-3,4],[2,-2],[-2,2]],[matrix([0,2],[-2,-1]),[1,4],[4,4],[-1,0]],[matrix([3,3],[-2,2]),[3,1],[-3,-1],[1,4]],[matrix([0,-2],[-3,-1]),[-3,3],[3,-2],[2,0]],[matrix([3,3],[-2,-1]),[4,1],[-3,0],[-1,3]],[matrix([-3,2],[-3,-1]),[-3,-2],[1,-2],[-1,4]],[matrix([0,3],[1,-3]),[3,1],[1,0],[-3,-3]],[matrix([-2,-2],[-1,1]),[1,-3],[2,-3],[2,-1]],[matrix([-1,-2],[2,1]),[3,-3],[4,4],[1,2]]];
ix: 1+rand(10);
Mt: tlist[ix][1]; A: tlist[ix][2]; B: tlist[ix][3]; C: tlist[ix][4];
Ob: transpose(matrix(A,B,C));
ta: Mt.Ob;
/* diagnostics: columns of M used as rows; leading diagonal only */
dT: transpose(Mt).Ob;
dD: matrix([Mt[1,1],0],[0,Mt[2,2]]).Ob;
/* tests: the product rebuilt entry by entry; generic offset */
tr: matrix([Mt[1,1]*A[1]+Mt[1,2]*A[2], Mt[1,1]*B[1]+Mt[1,2]*B[2], Mt[1,1]*C[1]+Mt[1,2]*C[2]],[Mt[2,1]*A[1]+Mt[2,2]*A[2], Mt[2,1]*B[1]+Mt[2,2]*B[2], Mt[2,1]*C[1]+Mt[2,2]*C[2]]);
tw: ta+matrix([1,0,0],[0,0,0]);
xr: Mt[1,1]*x+Mt[1,2]*y; yr: Mt[2,1]*x+Mt[2,2]*y; xT: Mt[1,1]*x+Mt[2,1]*y;
cA: transpose(matrix(A)); cB: transpose(matrix(B)); cC: transpose(matrix(C));
